j.saveSoon()
j.log(1,Bxc[1715],string.format(Bxc[1716],eb.charmWords(Mn),tostring(Ln.label),math.floor((tonumber(Ln.p)or 0)*100+0.5),(tonumber(Ln.p)or 0)>=0.92 and Bxc[1707]or Bxc[1623]))
else
