function eb.weatherStrength(Pn)
local Qn=eb.fx(Pn)
local Rn=Qn.dmg/Qn.cd/Qn.hp/Qn.speed*(1+(Qn.range-1)/2)
for Sn,Tn in pairs(Qn.kinds)do
Rn=Rn*(1+Q.rogueShare(Sn)*Tn)
end
if Qn.ice>0 then
local Un=Q.rogueShare(Bxc[1668])
Rn=Rn*(Un+(1-Un)/(1-Qn.ice+Qn.ice/W.modFactor(Bxc[1718])))
end
if Qn.fly>0 then
Rn=Rn*(1-Qn.fly*0.5)
end
if Qn.noCC then
Rn=Rn*0.95
end
if Qn.shroud then
Rn=Rn*0.9
end
return Rn
end
function eb.cardGems(Vn,Wn)
