local ot=nt.calibrated or lt.runs>0
local pt=(nt.trust and nt.trust.ok)and 6 or(ot and 3 or 1.5)
local qt=(ot or nt.hopeless)and 0 or 2
return(lt.wins+mt*qt+nt.p*pt)/(lt.runs+qt+pt)
end
