function O.trialTeam()
local Kt=J.trial
local Lt=Kt.list[tonumber(Kt.i)or 1]
if J.train.on then
bb.home()
end
local Mt=H.session()
local Nt,Ot
for Pt,Qt in pairs(Mt.profile_data.collection.owned_units)do
if Qt.unit_id==Lt then
local Rt=Mt.collection:get_unit_by_uuid(Qt.uuid)or Qt
local St,Tt=pcall(N.score,Rt)
Tt=St and Tt or 0
