function ab.pullGoal()
local nC=I.pullGoal
if type(nC)~=Bxc[1491]or nC==Bxc[418]or type(H.Units[nC])~=Bxc[1489]then
return nil
end
local oC=H.prof()
if not oC then
return nil
end
local pC=H.Units[nC]
local qC=pC.evolve and pC.evolve.evolve_unit or nC
local rC={id=nC,to=qC,coins=H.cur(Bxc[2016]),itemCost=0,needCoins=0}
for sC,tC in pairs(pC.evolve and pC.evolve.normal and pC.evolve.normal.item_requirement or{})do
local uC=H.SaleEvent[tC.item_id]
if uC and type(uC.resource_cost)==Bxc[1489]and uC.resource_cost.id==Bxc[2016]then
rC.item,rC.itemCost=tC.item_id,tonumber(uC.resource_cost.amount)or 0
end
end
rC.haveItem=rC.item~=nil and ab.have(rC.item)>0
local vC,wC=P.hatched[nC]or false,false
for xC,yC in pairs(oC.collection.owned_units)do
if yC.unit_id==nC then
vC=true
end
if yC.unit_id==qC then
wC=true
end
end
if wC then
rC.step=Bxc[2017]
elseif not vC then
rC.step,rC.needCoins=Bxc[2018],1
elseif rC.item and not rC.haveItem then
rC.step,rC.needCoins=Bxc[1986],math.max(0,rC.itemCost-rC.coins)
else
rC.step=Bxc[2019]
end
return rC
end
function ab.goalText()
local zC=ab.pullGoal()
if not zC then
return Bxc[2020]
end
local AC=H.prof()
local BC=string.format(Bxc[2021],N.name(zC.to),(ab.tier(zC.to))and(Bxc[2022]..ab.tier(zC.to)..Bxc[1806])or Bxc[418])
if zC.step==Bxc[2018]then
if not H.Banners.April2025 then
return BC..string.format(Bxc[2023],N.name(zC.id))
end
local CC=math.max(I.aprilFloor,zC.haveItem and 0 or zC.itemCost)
local DC=AC and AC.pity_data and AC.pity_data.April2025
local EC=DC and tonumber(DC.opens_since_mythic)
return BC..string.format(Bxc[2024]..Bxc[2025]..Bxc[2026],N.name(zC.id),M.fmt(zC.coins),math.max(0,math.floor((zC.coins-CC)/1500)),M.fmt(CC),N.name(zC.id),EC and string.format(Bxc[2027],EC)or Bxc[418],math.max(I.aprilValue,I.goalCoinValue),I.summonApril and Bxc[2028]or Bxc[2029])
elseif zC.step==Bxc[1986]then
return BC..string.format(Bxc[2030],N.name(zC.id),M.fmt(zC.itemCost),M.fmt(zC.coins))
elseif zC.step==Bxc[2019]then
return BC..Bxc[2031]
end
return BC..Bxc[2032]
end
function P.eventShop()
local FC=ab.pullGoal()
if not(I.summonApril and FC and FC.step==Bxc[1986]and FC.coins>=FC.itemCost and FC.itemCost>0)then
return
end
if j.req.back.eshop and M.now()<j.req.back.eshop then
return
end
local GC,HC=j.request(Bxc[2033],Bxc[1788],FC.item,Bxc[1506],Bxc[1789],Bxc[1627])
local IC=M.now()
while M.now()-IC<4 and ab.have(FC.item)<1 do
task.wait(0.25)
end
local JC=(H.Items[FC.item]or{}).name or FC.item
if ab.have(FC.item)>0 then
R.add(JC,FC.itemCost,Bxc[2016],Bxc[2034]..N.name(FC.to))
if j.notify then
j.notify(Bxc[71],Bxc[2035]..JC..Bxc[2036]..N.name(FC.id),Bxc[2037])
end
pcall(ab.refresh)
else
j.log(1,Bxc[2038],Bxc[2039]..tostring(FC.item)..Bxc[1805]..tostring(GC and HC or Bxc[1771])..Bxc[1806])
j.backoff(Bxc[2033],900)
end
end
function P.codes()
if not I.codes then
return j.status(Bxc[99],Bxc[2040])
end
local KC=H.prof()
if not KC then
return
end
local LC=KC.redeemed_codes or{}
local MC,NC={},{}
for OC,QC in ipairs(H.CODES)do
local RC=tonumber(J.codes[QC])
if LC[QC]then
if RC and RC>0 then
table.insert(NC,QC)
J.codes[QC]= -1
end
elseif os.time()-(RC or 0)>86400 and(RC or 0)>=0 then
J.codes[QC]=os.time()
local SC=j.request(Bxc[2041],Bxc[2042],QC)
if SC then
table.insert(MC,QC)
end
task.wait(1)
end
end
if#NC>0 then
j.log(1,Bxc[2043],Bxc[2044]..table.concat(NC,Bxc[1585]))
end
if#MC>0 then
j.log(1,Bxc[2043],Bxc[2045]..table.concat(MC,Bxc[1585])..Bxc[2046])
end
j.saveSoon()
local TC=0
for UC,VC in ipairs(H.CODES)do
if not LC[VC]then
TC=TC+1
end
end
j.status(Bxc[99],#MC>0 and(Bxc[2045]..table.concat(MC,Bxc[1585]))or(TC==0 and Bxc[2047]or(TC..Bxc[2048])))
end
