function ab.bestSource(cD)
if not(O.lastScored and O.lastScored[1])then
pcall(O.pick)
end
local dD={}
for eD,fD in ipairs(O.lastScored or{})do
if fD.level then
dD[fD.level]=fD
end
end
local gD,hD
for iD,jD in ipairs(cD or{})do
local kD=dD[jD.level]
local lD,mD=pcall(function()
return kD and O.minutes(kD)or 10
end)
local nD=jD.per*(kD and(kD.p or 0.5)or 0.5)/math.max(1,lD and mD or 10)
if not hD or nD>hD then
gD,hD=jD,nD
end
end
return gD
end
function ab.planItem(oD,pD)
local qD=ab.have(oD)
if qD>=pD then
return{item=oD,done=true}
end
local rD=ab.sources()[oD]
if rD and rD[1]then
return{item=oD,need=pD,have=qD,farm=oD,farmNeed=pD-qD,levels=rD}
end
local sD=H.SaleEvent[oD]
if sD and type(sD.resource_cost)==Bxc[1489]then
return{item=oD,need=pD,have=qD,eventShop=true,cost=tonumber(sD.resource_cost.amount)or 0,currency=sD.resource_cost.id,farmNeed=0}
end
for tD,uD in pairs(J.raidShop)do
if uD.id==oD and uD.costItem and(uD.stock==Bxc[2049]or(tonumber(uD.stock)or 0)>0)then
local vD=ab.sources()[uD.costItem]
local wD=uD.cost*(pD-qD)
local xD=ab.have(uD.costItem)
return{item=oD,need=pD,have=qD,shopKey=tD,costItem=uD.costItem,cost=uD.cost,farm=uD.costItem,farmNeed=math.max(0,wD-xD),levels=vD or{}}
end
end
for yD,zD in pairs(O.PORTALS)do
if zD.item==oD then
return{item=oD,need=pD,have=qD,farm=oD,farmNeed=pD-qD,portal=yD,levels={{level=zD.level,per=O.portalPer(yD)}}}
