function db.gainXp(pK,qK)
local rK,sK=tonumber(pK.xp)or 0,db.xpFor(pK.unit_id,db.cap(pK))
local tK=math.max(0,sK-rK)
if tK<=0 or(qK or 0)<=0 then
return 0,0
end
local uK=math.min(qK,tK)
local vK=db.base(pK)
if vK<=0 then
return 0,uK
end
return db.share(pK.unit_id)*(db.score(db.whatIf(pK,{xp=rK+uK}))/vK-1)*100,uK
end
function db.gainFuse(wK)
if db.lb(wK)>=1 then
return 0
end
local xK=db.base(wK)
if xK<=0 then
return 0
end
local yK=db.whatIf(wK,{xp=math.max(tonumber(wK.xp)or 0,db.xpFor(wK.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(wK.unit_id)*(db.score(yK)/xK-1)*100+5
end
