function db.relicWorth(zK,AK)
local BK=AK._unique_item_data and AK._unique_item_data._unique_relic_data
if not BK then
return 0
end
local CK=H.Items[AK.item_id]or{}
local DK,EK=N.types(zK.unit_id)
if CK.main_damage_type and CK.main_damage_type~=Bxc[2109]and CK.main_damage_type~=EK then
return 0
end
local FK,GK=0,0
for HK,IK in pairs(BK._core_damage_type_buffs or{})do
if DK[IK.damage_type]then
FK=FK+(tonumber(IK.mul)or 0)+(tonumber(IK.add_upg)or 0)*0.01+(tonumber(IK.pen)or 0)*0.001
GK=GK+(tonumber(IK.crit)or 0)
end
end
FK=FK+GK*0.5
local JK=N.rows(zK.unit_id)
local KK=JK and JK[JK.max]
local LK=(KK and tonumber(KK.cd)or 0)*N.mult(zK,Bxc[1624])
for MK,NK in pairs(BK._unique_relic_effects or{})do
local OK=type(NK.params)==Bxc[1489]and NK.params or{}
if NK.id==Bxc[2110]then
local PK=math.min(1,(tonumber(OK.extra_damage)or 0)*LK/math.max(1,tonumber(OK.time_interval)or 40))
local QK=N.DRONES and N.DRONES[zK.unit_id]
if QK and QK.late and LK>0 then
local RK=1/LK
PK=PK*RK/(RK+(tonumber(QK.max)or 0)*(tonumber(QK.late.dmg)or 0)*(tonumber(QK.hits)or 1)/math.max(0.1,tonumber(QK.late.cd)or 4))
end
FK=FK+PK
elseif NK.id==Bxc[2111]then
FK=FK+(tonumber(OK.dmg_buff)or 0)*0.25
elseif NK.id==Bxc[2112]then
FK=FK+(tonumber(OK.dmg_buff)or 0)*GK
elseif NK.id==Bxc[2113]then
if DK.magic then
FK=0
else
FK=FK+(tonumber(OK.dmg_buff)or 0)*0.3
end
elseif NK.id==Bxc[2114]then
if DK.water_damage then
FK=FK+0.05
end
end
end
return FK
end
function db.relicPlan()
