function P.fuseFuel(zQ,AQ)
local BQ=H.session()
local CQ={[zQ.uuid]=true,[I.evolveUnit]=true,[I.fuseXpUnit]=true}
local DQ={}
for EQ,FQ in ipairs(N.equipped())do
CQ[FQ.uuid]=true
end
for GQ,HQ in ipairs(J.savedTeam or{})do
CQ[HQ]=true
end
for IQ,JQ in ipairs(J.train and J.train.on and J.train.on.base or{})do
CQ[JQ]=true
end
for KQ,LQ in ipairs(J.goals or{})do
CQ[LQ.uuid]=true
for MQ,NQ in ipairs(LQ.eats or{})do
DQ[NQ.id]=true
end
end
for OQ,PQ in ipairs(J.str and J.str.core or{})do
CQ[PQ]=true
end
local QQ=ab.strongest(10)
local RQ,SQ={},0
for TQ,UQ in pairs(BQ.profile_data.collection.owned_units)do
local VQ=BQ.collection:get_unit_by_uuid(TQ)or UQ
local WQ,XQ,YQ=pcall(H.USC.is_unit_good_for_fusion,zQ,VQ)
if WQ and XQ and not(UQ._locked or VQ._locked)and not CQ[TQ]and not DQ[VQ.unit_id]and not(UQ._equipped_relic or VQ._equipped_relic)and not(UQ.shiny or VQ.shiny)and not N.trait(VQ)and not(UQ.further_modifiers and UQ.further_modifiers.limit_break)then
local ZQ=ab.fodderOrder(VQ.unit_id)
if ZQ and not QQ[TQ]then
local _Q,aR=pcall(N.score,VQ)
table.insert(RQ,{uuid=TQ,id=VQ.unit_id,pts=tonumber(YQ)or 1,sc=_Q and aR or 0,order=ZQ})
SQ=SQ+(tonumber(YQ)or 1)
end
end
end
table.sort(RQ,function(bR,cR)
