end
local Lwb=tostring(Iwb.r._r or(Iwb.d..Bxc[1600]..Iwb.choice))..(Jwb and(Bxc[2332]..tostring(Jwb))or Bxc[418])..(Kwb and Bxc[2795]or Bxc[418])
local Mwb=cb.data()
