else
local Vwb=W.evaluate(Twb,W.teamFrom(Qwb,Twb.map))
Pwb={p=Vwb.p,wave=Vwb.wave,won=Vwb.won,total=Twb.total,margin=Vwb.margin,sig=Owb,at=os.time()}
