local cxb=M.clamp(0.95-0.015*_wb.d,0.5,0.95)
local dxb=((tonumber(bxb.wins)or 0)+cxb*2)/((tonumber(bxb.runs)or 0)+2)
local exb,fxb=pcall(cb.sim,_wb)
if exb and fxb and fxb.p then
dxb=(dxb*2+fxb.p)/3
end
return dxb,exb and fxb or nil
end
function cb.hopeless(gxb)
