function cb.curseOk(qxb,rxb,sxb,txb,uxb)
local vxb=tostring((cb.item(qxb)or{}).name or qxb)
local wxb,xxb,yxb=cb.curseBar(rxb,sxb)
if wxb>0.2 and cb.blindCurse(rxb,qxb)then
return false,string.format(Bxc[2801],vxb,yxb)
end
local function zxb(Axb)
return Axb==nil or(tonumber(Axb.p)or 1)>=wxb
end
if txb then
local Bxb,Cxb=pcall(cb.sim,txb,nil,true)
if Bxb and not zxb(Cxb)then
return false,string.format(Bxc[2802],vxb,(xxb:gsub(Bxc[2803],Bxc[2804])),tostring(Cxb.margin or Bxc[1726]))
end
end
if#uxb==0 then
return true
end
local Dxb
for Exb,Fxb in ipairs(uxb)do
local Gxb,Hxb=pcall(cb.sim,Fxb,qxb,true)
if not Gxb or zxb(Hxb)then
return true
end
if not Dxb or(tonumber(Hxb.p)or 0)>(tonumber(Dxb.p)or 0)then
Dxb=Hxb
end
end
