function cb.pick(Sxb)
local Txb,Uxb=cb.curses(Sxb),cb.lives(Sxb)
local Vxb=cb.res(Sxb)
local Wxb=cb.rooms(Sxb)
local Xxb={}
for Yxb,Zxb in ipairs(Wxb)do
table.insert(Xxb,tostring(Zxb.r._r))
end
local _xb=table.concat(Xxb,Bxc[2104])..string.format(Bxc[2806],Uxb,Vxb,Txb,O.teamSig())
if cb._pick and cb._pick.sig==_xb then
return cb._pick.x
end
local ayb,byb
for cyb,dyb in ipairs(Wxb)do
local eyb=cb.roomValue(dyb,Vxb)
local fyb,gyb
for hyb,iyb in ipairs(cb.after(Sxb,dyb.choice))do
local jyb=cb.roomValue(iyb,Vxb)
if not fyb or jyb>fyb then
fyb,gyb=jyb,iyb
end
end
local kyb,lyb=cb.winP(dyb)
local myb=1-(1-kyb)^math.max(1,Uxb)
local nyb=Uxb>=3 and 1 or(Uxb==2 and 2 or 6)
dyb.p,dyb.sim,dyb.value,dyb.nextValue,dyb.nextRoom=kyb,lyb,eyb,fyb or 0,gyb
dyb.score=myb*(eyb+0.6*(fyb or 0))-(1-kyb)*nyb
local oyb,pyb,qyb=pcall(cb.curseGate,dyb,Sxb)
if oyb and not pyb then
dyb.blocked=qyb
end
if not dyb.blocked and(not ayb or dyb.score>ayb.score)then
ayb=dyb
end
if not byb or dyb.score>byb.score then
byb=dyb
end
end
ayb=ayb or byb
cb._pick={sig=_xb,x=ayb,rooms=Wxb}
return ayb
end
