local rzb={}
local szb,tzb={},0
for uzb,vzb in ipairs(cb.offers(mzb and mzb.data))do
vzb.cost=math.ceil(vzb.cost*pzb)
table.insert(szb,tostring(cb.item(vzb.id).name or vzb.id))
if not vzb.bought and not cb.isCurse(vzb.id)then
vzb.luck=tonumber(cb.item(vzb.id).luck_increase)~=nil
vzb.v=cb.itemValue(vzb.id,lzb)
if not vzb.luck and vzb.v/math.max(1,vzb.cost)<cb.MIN_WORTH then
tzb=tzb+1
