end)
local yzb,zzb,Azb={},0,0
for Bzb,Czb in ipairs(rzb)do
if Czb.cost<=ozb-(Czb.luck and 0 or qzb)then
if cb.buy(Czb)then
ozb=cb.res(cb.data())
table.insert(yzb,string.format(Bxc[2818],tostring(cb.item(Czb.id).name or Czb.id),Czb.cost))
end
elseif Czb.cost<=ozb then
Azb=Azb+1
else
zzb=zzb+1
end
end
cb.note(string.format(Bxc[2819],nzb,#szb>0 and table.concat(szb,Bxc[1585])or Bxc[2820],#yzb>0 and(Bxc[2821]..table.concat(yzb,Bxc[1585]))or(nzb<10 and Bxc[2822]or(Azb>0 and Bxc[2823]or Bxc[2824])),ozb,zzb>0 and string.format(Bxc[2825],zzb)or Bxc[418],Azb>0 and string.format(Bxc[2826],Azb,qzb)or Bxc[418],tzb>0 and string.format(Bxc[2827],tzb)or Bxc[418]))
j.request(Bxc[2828],Bxc[2829])
end
function cb.shrine(Dzb,Ezb)
