return tostring(Q.ld and Q.ld.map or Bxc[1726])..(Q.laneCut and(Bxc[2916]..Q.laneCut)or Bxc[418])
end
function Q.label()
if Q.kind==Bxc[1509]then
local rDb=type(Q.ld._dungeon)==Bxc[1489]and Q.ld._dungeon.depth or Bxc[1726]
return string.format(Bxc[2917],tostring(rDb),cb.ROOMS,tostring(Q.ld._location_name or Q.ld.map or Bxc[1726]))
end
return O.levelName(Q.ld.id or Bxc[1726])..(Q.ld._difficulty and(Bxc[1805]..Q.ld._difficulty..Bxc[1806])or Bxc[418])
end
function Q.money()
local sDb=G:FindFirstChild(Bxc[1548])
return sDb and sDb.resource.Value or 0
end
function Q.wave()
return workspace:FindFirstChild(Bxc[2918])and workspace._wave_num.Value or 0
end
function Q.buildPath()
Q.samples={}
local tDb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not tDb then
return
end
for uDb,vDb in pairs(tDb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[uDb.Name])then
local wDb={}
for xDb,yDb in ipairs(vDb.points or{})do
table.insert(wDb,yDb.part.Position)
end
local zDb=0
for ADb=2,#wDb do
zDb=zDb+(wDb[ADb]-wDb[ADb-1]).Magnitude
end
local BDb=0
for CDb=2,#wDb do
local DDb,EDb=wDb[CDb-1],wDb[CDb]
local FDb=(EDb-DDb).Magnitude
local GDb=math.max(1,math.floor(FDb/2))
for HDb=0,GDb-1 do
local IDb=DDb:Lerp(EDb,HDb/GDb)
table.insert(Q.samples,{pos=IDb,prog=(BDb+FDb*HDb/GDb)/math.max(1,zDb),lane=uDb.Name})
end
BDb=BDb+FDb
end
if wDb[#wDb]then
table.insert(Q.samples,{pos=wDb[#wDb],prog=1,lane=uDb.Name})
end
end
end
Q.laneCut,Q.laneWant,Q.laneFirst=nil,nil,nil
local JDb=tonumber(Q.ld and Q.ld._portal_lanes)
local KDb=W.laneList(Q.samples)
if JDb and JDb>=1 and KDb and#KDb>JDb then
Q.laneWant=JDb
end
Q.laneTotal=KDb and#KDb or 1
Q.countLanes()
end
function Q.countLanes()
local LDb,MDb,NDb={},0,0
for ODb,PDb in ipairs(Q.samples)do
local QDb=tostring(PDb.lane)
if not LDb[QDb]then
MDb=MDb+1
end
LDb[QDb]=(LDb[QDb]or 0)+1
NDb=NDb+1
end
Q.laneCount={n=MDb,by=LDb,avg=MDb>0 and NDb/MDb or 1}
end
function Q.portalLanes()
if not Q.laneWant or Q.laneCut then
return true
end
if Q.planning then
return false
end
local RDb,SDb={},0
for TDb,UDb in ipairs(workspace._UNITS:GetChildren())do
local VDb=UDb:FindFirstChild(Bxc[1548])
if VDb and VDb:FindFirstChild(Bxc[2919])and VDb.player.Value==nil and VDb:FindFirstChild(Bxc[2920])and UDb:FindFirstChild(Bxc[2921])then
local WDb=tostring(VDb.lane.Value)
if not RDb[WDb]then
RDb[WDb]=true
SDb=SDb+1
end
end
end
if SDb==0 then
if M.now()-(Q.startT or M.now())>45 then
Q.laneWant=nil
j.log(1,Bxc[2922],Bxc[2923])
return true
end
return false
end
Q.laneFirst=Q.laneFirst or M.now()
if SDb<Q.laneWant and M.now()-Q.laneFirst<10 then
return false
end
local XDb,YDb={},{}
for ZDb,_Db in ipairs(Q.samples)do
if RDb[tostring(_Db.lane)]then
table.insert(XDb,_Db)
end
end
if#XDb==0 then
Q.laneWant=nil
return true
end
for aEb in pairs(RDb)do
table.insert(YDb,aEb)
end
table.sort(YDb)
Q.samples,Q.laneCut=XDb,table.concat(YDb,Bxc[2332])
Q.countLanes()
local bEb,cEb=pcall(Q.buildCandidates)
if not bEb then
j.log(1,Bxc[1863],Bxc[2924]..tostring(cEb))
end
j.log(1,Bxc[2922],string.format(Bxc[2925],Q.laneWant,Q.laneCut))
if Q.info and I.simSpots and not Q.joinedMid and not Q.random and not Q.infinite and not Q.trialId then
Q.planning=M.now()
task.spawn(function()
local dEb,eEb=pcall(Q.planSpots)
Q.planning=nil
if not dEb then
j.log(1,Bxc[1863],Bxc[2926]..tostring(eEb))
end
end)
end
return true
end
function Q.buildWaves()
local fEb=Q.ld
local gEb=fEb and fEb._dungeon and type(fEb._override_waves)==Bxc[1489]and fEb._override_waves or nil
local hEb=fEb and H.Waves[(gEb and gEb.template)or fEb.waves or fEb.id]
local iEb
if type(hEb)==Bxc[1489]then
iEb=hEb.override_waves or hEb.waves
if not iEb and hEb.template and H.Waves[hEb.template]then
iEb=H.Waves[hEb.template].waves or H.Waves[hEb.template].override_waves
end
end
Q.waveList=M.list(iEb)
Q.infinite=fEb and(fEb._gamemode==Bxc[1508]or fEb.infinite)and W.unbound(fEb)or false
if Q.infinite then
Q.waveList={}
Q.total=math.max(30,math.floor(O.infReach(Q.key)+0.5))
return
end
Q.total=(fEb and type(fEb._dungeon)==Bxc[1489]and 15)or tonumber(fEb and fEb._override_infinite_bound_waves)or W.boundEnd(fEb,#Q.waveList,Q.key)or(#Q.waveList>0 and#Q.waveList)or 15
end
function Q.infExtend()
if Q.infinite and Q.wave()+5>Q.total then
Q.total=Q.wave()+10
end
end
function Q.infWave(jEb)
Q.infExtend()
if I.trainLeave and not Q.stopping then
local kEb,lEb=pcall(Q.trainLeave,jEb)
if not kEb then
j.log(1,Bxc[1863],Bxc[2927]..tostring(lEb))
end
end
if I.infiniteStop and not Q.stopping then
local mEb,nEb=pcall(Q.infStop,jEb)
if not mEb then
j.log(1,Bxc[1863],Bxc[2928]..tostring(nEb))
end
end
local oEb=O.infTier(jEb-1)
if oEb<=0 or oEb==Q.infTierSeen then
return
end
Q.infTierSeen=oEb
task.delay(5,function()
if not j.alive then
return
end
local pEb=H.prof()
local qEb=pEb and pEb.daily_infinite_reward_claims and pEb.daily_infinite_reward_claims[Q.ld.id]
local rEb=type(qEb)==Bxc[1489]and(tonumber(qEb.highest_claimed_wave)or 0)>=oEb and os.time()-(tonumber(qEb.highest_claim_time)or 0)<900
if rEb then
J.infLive=true
end
j.log(1,Bxc[2922],string.format(Bxc[2929],oEb,rEb and Bxc[2930]or Bxc[2931]))
end)
end
function Q.infStop(sEb)
local tEb=0
for uEb,vEb in ipairs(M.list(H.GS.DAILY_INFINITE_REWARDS))do
tEb=math.max(tEb,tonumber(vEb.wave)or 0)
end
if tEb<=0 or sEb<=tEb+1 then
return
end
local wEb=J.train.on
if Q.trainee and wEb and wEb.have+(wEb.got or 0)+(Q.trainTk or 0)<wEb.need then
return
end
if not P.every(Bxc[2932],60)then
return
end
local xEb=O.rec(Q.key)
local yEb=tonumber(xEb.timed)or 0
local zEb=(yEb>0 and(xEb.sec or 0)>0)and math.max(0.5,((xEb.gems or 0)-200*yEb)/(xEb.sec/60))or 2.5
local AEb=pcall(O.pick)
local BEb
for CEb,DEb in ipairs(AEb and O.lastScored or{})do
if DEb.kind~=Bxc[1508]and(not BEb or(DEb.score or 0)>(BEb.score or 0))then
BEb=DEb
end
end
if not BEb or(BEb.score or 0)<=zEb then
return
end
Q.stopping=true
j.log(1,Bxc[2922],string.format(Bxc[2933],sEb,zEb,BEb.score,BEb.label))
Q.sellAll()
end
function Q.trainLeave(EEb)
local FEb=J.train.on
if not(Q.infinite and Q.trainee and FEb)then
return
end
Q.trainCount()
local GEb=FEb.have+(FEb.got or 0)+(Q.trainTk or 0)
if GEb<FEb.need then
return
end
local HEb,IEb,JEb=pcall(O.infDaily,H.prof(),Q.ld.id,(O.infReach(Q.key)))
if HEb and(IEb or 0)>0 and JEb>0 and EEb<=JEb then
j.status(Bxc[2352],string.format(Bxc[2934],N.name(FEb.id),FEb.what,JEb))
return
end
Q.stopping=true
j.log(1,Bxc[2922],string.format(Bxc[2935],N.name(FEb.id),FEb.what,M.fmt(GEb),M.fmt(FEb.need),EEb))
Q.sellAll()
end
function Q.sellAll()
task.spawn(function()
local KEb={}
for LEb,MEb in ipairs(Q.mine or{})do
local NEb=MEb:FindFirstChild(Bxc[1548])
local OEb=NEb and NEb:FindFirstChild(Bxc[2666])and H.Units[NEb.id.Value]
if not(OEb and OEb.unsellable)then
table.insert(KEb,MEb)
end
end
local function PEb(QEb)
local REb=QEb:FindFirstChild(Bxc[1548])
return REb and REb:FindFirstChild(Bxc[2666])and N.isFarm(REb.id.Value)or false
end
table.sort(KEb,function(SEb,TEb)
return(PEb(SEb)and 1 or 0)<(PEb(TEb)and 1 or 0)
end)
local UEb={}
for VEb=1,2 do
local WEb={}
for XEb,YEb in ipairs(VEb==1 and KEb or UEb)do
if not j.alive or Q.finished then
return
end
if YEb.Parent and YEb.Parent.Name==Bxc[2936]then
local ZEb,_Eb=j.request(Bxc[2937],Bxc[2938],YEb)
if _Eb~=true then
table.insert(WEb,YEb)
end
task.wait(1.3)
end
end
UEb=WEb
end
if#UEb>0 then
local aFb={}
for bFb,cFb in ipairs(UEb)do
table.insert(aFb,cFb.Name)
end
j.log(1,Bxc[2922],Bxc[2939]..table.concat(aFb,Bxc[1585])..Bxc[2940])
end
end)
end
function Q.waveReward(dFb)
if Q.info then
return W.waveYen(Q.info,dFb)
end
local eFb=Q.waveList and Q.waveList[dFb]
return(eFb and tonumber(eFb.wave_reward)or 0)*2.6
end
function Q.progressAt(fFb)
local gFb,hFb,iFb=0,math.huge,nil
local jFb=M.flat(fFb)
for kFb,lFb in ipairs(Q.samples)do
local mFb=(M.flat(lFb.pos)-jFb).Magnitude
if mFb<hFb then
hFb,gFb,iFb=mFb,lFb.prog,lFb.lane
end
end
return gFb,hFb,iFb~=nil and tostring(iFb)or nil
end
function Q.scan()
local nFb,oFb={},{}
for pFb,qFb in ipairs({workspace._UNITS})do
for rFb,sFb in ipairs(qFb:GetChildren())do
local tFb=sFb:FindFirstChild(Bxc[1548])
if tFb and tFb:FindFirstChild(Bxc[2919])then
local uFb=tFb:FindFirstChild(Bxc[2941])
local vFb=uFb and uFb.Value
local wFb=vFb and vFb:FindFirstChild(Bxc[1548])
local xFb=H.Units[tFb.id.Value]
local yFb=vFb~=nil and xFb~=nil and(tonumber(xFb.cost)or 0)>=100 and(not wFb or(wFb:FindFirstChild(Bxc[2666])and wFb.id.Value==tFb.id.Value))
if tFb.id.Value==Bxc[2942]then
yFb=true
end
local zFb=(vFb~=nil and not yFb)or not tFb:FindFirstChild(Bxc[1624])or not tFb:FindFirstChild(Bxc[1575])or not tFb:FindFirstChild(Bxc[1626])
if tFb.player.Value==G then
if not zFb then
table.insert(oFb,sFb)
end
elseif tFb.player.Value==nil and sFb:FindFirstChild(Bxc[2921])then
local AFb,BFb,CFb=Q.progressAt(sFb.HumanoidRootPart.Position)
local DFb=sFb:FindFirstChildOfClass(Bxc[2943])
local EFb=DFb and DFb.Health or(tFb:FindFirstChild(Bxc[2559])and tFb.health.Value)or 0
local FFb=tFb:FindFirstChild(Bxc[2689])and tonumber(tFb.damage_reduction.Value)or 0
local GFb=Q.info and Q.info.cfgById[tFb.id.Value]
local HFb=tFb:FindFirstChild(Bxc[2786])and(tonumber(tFb.Flying.Value)or 0)>0 or false
local IFb=tFb:FindFirstChild(Bxc[1888])and tonumber(tFb.shield.Value)or 0
table.insert(nFb,{m=sFb,pos=sFb.HumanoidRootPart.Position,prog=AFb,lane=CFb,hp=EFb,red=FFb,fly=HFb,sh=IFb,boss=GFb and tostring(GFb):find(Bxc[1891])~=nil or false})
if tostring(tFb.id.Value):find(Bxc[2944])then
pcall(Q.noteStar,sFb,DFb)
end
end
end
end
end
Q.enemies,Q.mine=nFb,oFb
if not Q.flyerSeen then
for JFb,KFb in ipairs(nFb)do
if KFb.fly then
Q.flyerSeen=math.max(1,Q.wave())
if not Q.random then
j.log(1,Bxc[2922],string.format(Bxc[2945],Q.flyerSeen))
end
break
end
end
end
if not Q.shieldSeen then
for LFb,MFb in ipairs(nFb)do
if(MFb.sh or 0)>0 then
Q.shieldSeen=true
local NFb=MFb.m._stats
j.log(1,Bxc[2922],string.format(Bxc[2946],Q.wave(),tostring(MFb.sh),tostring(NFb:FindFirstChild(Bxc[2947])and NFb.max_shield.Value),tostring(NFb:FindFirstChild(Bxc[2666])and NFb.id.Value),MFb.hp,tostring(Q.info and Q.info.shield)))
break
end
end
end
local OFb=Q.wave()
local PFb=0
local QFb,RFb,SFb=0,0,0
for TFb,UFb in ipairs(nFb)do
PFb=math.max(PFb,UFb.prog)
QFb=QFb+UFb.hp/math.max(0.1,1-UFb.red)
SFb=SFb+UFb.hp
end
Q.hpAliveRaw=SFb
for VFb,WFb in ipairs(oFb)do
local XFb=WFb._stats.id.Value
if not N.isFarm(XFb)and WFb._stats:FindFirstChild(Bxc[1623])then
local YFb,ZFb=pcall(Q.liveDps,WFb,XFb)
if YFb and ZFb then
RFb=RFb+ZFb
end
end
end
Q.hpAlive,Q.teamDps=QFb,RFb
Q.clearSec=QFb>0 and(RFb>0 and QFb/RFb or math.huge)or 0
Q.waveMax[OFb]=math.max(Q.waveMax[OFb]or 0,PFb)
Q.front=PFb
Q.pressure=math.max(Q.waveMax[OFb]or 0,Q.waveMax[OFb-1]or 0)
Q.depth=Q.coverage(oFb,nFb)
local _Fb=M.now()
Q.aliveHist=Q.aliveHist or{}
table.insert(Q.aliveHist,{t=_Fb,n= #nFb})
while Q.aliveHist[1]and _Fb-Q.aliveHist[1].t>12 do
table.remove(Q.aliveHist,1)
end
local aGb=Q.aliveHist[1]
Q.piling= #nFb>=8 and aGb and _Fb-aGb.t>=8 and#nFb>aGb.n+1 or false
if#nFb>=18 then
Q.piling=true
end
end
function Q.setupChecks()
Q.probe=Instance.new(Bxc[2948])
Q.probe.Name=Bxc[2949]
Q.probe.Anchored=true
Q.probe.CanCollide=false
Q.probe.CanTouch=false
Q.probe.CanQuery=false
Q.probe.Transparency=1
Q.probe.Parent=workspace:FindFirstChild(Bxc[2950])or workspace
local bGb=E:FindFirstChild(Bxc[2951])
Q.bounds=Instance.new(Bxc[2952])
Q.bounds.Name=Bxc[2953]
if bGb then
for cGb,dGb in ipairs(bGb:GetDescendants())do
if dGb:IsA(Bxc[2954])then
local eGb=dGb:Clone()
for fGb,gGb in ipairs(eGb:GetChildren())do
gGb:Destroy()
end
eGb.Anchored=true
eGb.CanCollide=false
eGb.CanTouch=false
eGb.CanQuery=true
eGb.Transparency=1
eGb.CFrame=dGb.CFrame
eGb.Parent=Q.bounds
end
end
end
Q.bounds.Parent=workspace:FindFirstChild(Bxc[2950])or workspace
Q.overlap=OverlapParams.new()
Q.overlap.FilterType=Enum.RaycastFilterType.Include
Q.overlap.FilterDescendantsInstances={workspace._road,Q.bounds}
end
function Q.spotKey(hGb)
return string.format(Bxc[2955],math.floor(hGb.X+0.5),math.floor(hGb.Z+0.5))
end
function Q.killZone()
return I.killZone~=false and(Q.style==Bxc[2702]or(Q.style==nil and Q.kind==Bxc[1509]))
end
function Q.blockedSpot(iGb)
local jGb=Q.spotKey(iGb)
if Q.refused[jGb]then
return true
end
local kGb=J.blocked[Q.mapKey()]
return kGb and(tonumber(kGb[jGb])or 0)>=2
end
function Q.valid(lGb,mGb)
local nGb=H.PC.raycast(lGb+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not nGb then
return nil
end
if not H.PC.is_valid_raycast_hit(nGb.Instance,mGb)then
return nil
end
local oGb=nGb.Position
if Q.blockedSpot(oGb)then
return nil
end
local pGb=(tonumber(mGb.override_hitbox_radius)or 1.5)+0.25
Q.probe.Size=Vector3 .new(pGb*2,2.5,pGb*2)
Q.probe.CFrame=CFrame.new(oGb+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(Q.probe,Q.overlap)>0 then
return nil
end
for qGb,rGb in ipairs(Q.mine or{})do
local sGb=rGb:FindFirstChild(Bxc[2956])
local tGb=sGb and sGb.Position or rGb:GetPivot().Position
local uGb=sGb and math.max(sGb.Size.X,sGb.Size.Z)/2 or 1.5
if(M.flat(oGb)-M.flat(tGb)).Magnitude<pGb+uGb then
return nil
end
end
return oGb
end
function Q.buildCandidates()
Q.cands={}
local vGb={}
for wGb=1,#Q.samples,3 do
local xGb=Q.samples[wGb]
local yGb=Q.samples[math.min(#Q.samples,wGb+1)]
local zGb=M.flat(yGb.pos-xGb.pos)
if zGb.Magnitude<0.01 then
zGb=Vector3 .new(1,0,0)
end
zGb=zGb.Unit
local AGb=Vector3 .new(-zGb.Z,0,zGb.X)
for BGb,CGb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for DGb,EGb in ipairs({1,-1})do
local FGb=xGb.pos+AGb*CGb*EGb
local GGb=string.format(Bxc[2955],math.floor(FGb.X/1.5),math.floor(FGb.Z/1.5))
if not vGb[GGb]then
vGb[GGb]=true
table.insert(Q.cands,FGb)
end
end
end
end
end
function Q.coverage(HGb,IGb)
local JGb={}
for KGb,LGb in ipairs(HGb)do
local MGb=LGb._stats
if not N.isFarm(MGb.id.Value)and MGb:FindFirstChild(Bxc[1626])then
table.insert(JGb,{p=M.flat(LGb:GetPivot().Position),r=MGb.range.Value*(N.SUMMONER[MGb.id.Value]and N.SUMMONER[MGb.id.Value].reach or 1),air=Q.canAir(LGb)})
end
end
local NGb,OGb=0,0
if#JGb>0 then
for PGb,QGb in ipairs(Q.samples)do
if QGb.prog>OGb then
local RGb=M.flat(QGb.pos)
for SGb,TGb in ipairs(JGb)do
if(RGb-TGb.p).Magnitude<=TGb.r then
if QGb.prog>NGb then
NGb=QGb.prog
end
if TGb.air then
OGb=QGb.prog
break
end
end
end
end
end
end
local UGb,VGb={},Q.laneCount
if VGb and VGb.n>=2 and#JGb>0 then
local WGb={}
for XGb,YGb in ipairs(Q.samples)do
local ZGb=M.flat(YGb.pos)
for _Gb,aHb in ipairs(JGb)do
if(ZGb-aHb.p).Magnitude<=aHb.r then
local bHb=tostring(YGb.lane)
WGb[bHb]=(WGb[bHb]or 0)+1
if YGb.prog>(UGb[bHb]or 0)then
UGb[bHb]=YGb.prog
end
break
end
end
end
local cHb,dHb={},0
for eHb,fHb in pairs(VGb.by)do
cHb[eHb]=(WGb[eHb]or 0)/math.max(1,fHb)
dHb=math.max(dHb,cHb[eHb])
end
Q.laneW={}
for gHb,hHb in pairs(VGb.by)do
Q.laneW[gHb]=(VGb.avg/math.max(1,hHb))*(1+1.5*(dHb>0 and(1-cHb[gHb]/dHb)or 0))
end
Q.laneFrac=cHb
else
Q.laneW,Q.laneFrac=nil,nil
end
local iHb,jHb,kHb
if#JGb>0 then
for lHb,mHb in ipairs(IGb)do
local nHb=(Q.laneW and mHb.lane and UGb[mHb.lane])or NGb
if mHb.hp>0 and mHb.prog>nHb+0.02 and mHb.prog>(iHb or 0)then
iHb,kHb=mHb.prog,Q.laneW and mHb.lane or nil
end
if mHb.hp>0 and mHb.fly and mHb.prog>OGb+0.02 then
jHb=true
end
end
end
local oHb= #JGb>0 and(Q.pressure or 0)>=NGb-0.08
