Q.CONTROL_WORDS={Bxc[2996],Bxc[2997],Bxc[2998],Bxc[2999]}
function Q.controlSpot(NMb,OMb)
if not Q.killZone()then
return nil
end
local PMb=W.holds
if not PMb(NMb.id)or N.toggleOf(NMb.id)then
return nil
end
local QMb,RMb,SMb,TMb=1,0,0,{}
for UMb,VMb in ipairs(Q.mine or{})do
local WMb=VMb._stats
local XMb=WMb.id.Value
if WMb:FindFirstChild(Bxc[1626])and not N.isFarm(XMb)and not N.allyBuff(XMb)then
local YMb,ZMb=M.flat(VMb:GetPivot().Position),WMb.range.Value
if PMb(XMb)and not N.toggleOf(XMb)then
SMb=SMb+1
table.insert(TMb,{p=YMb,r=ZMb})
else
for _Mb,aNb in ipairs(Q.samples)do
if(M.flat(aNb.pos)-YMb).Magnitude<=ZMb then
QMb,RMb=math.min(QMb,aNb.prog),math.max(RMb,aNb.prog)
end
end
end
end
end
if RMb<=QMb then
QMb,RMb=0.75,0.98
end
local bNb=(OMb or SMb)+1
local cNb=({QMb,RMb,(QMb+RMb)/2,QMb-(RMb-QMb)/2})[bNb]
if not cNb then
return nil
end
local dNb=N.range(NMb.u,0)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local eNb={}
for fNb,gNb in ipairs(Q.cands)do
local hNb,iNb,jNb=M.flat(gNb),0,0
for kNb,lNb in ipairs(Q.samples)do
if(M.flat(lNb.pos)-hNb).Magnitude<=dNb then
jNb=jNb+1
if math.abs(lNb.prog-cNb)<=0.05 then
iNb=iNb+1
local mNb=M.flat(lNb.pos)
for nNb,oNb in ipairs(TMb)do
if(mNb-oNb.p).Magnitude<=oNb.r then
iNb=iNb-0.5
break
end
end
end
end
end
if iNb>0 then
table.insert(eNb,{pos=gNb,sc=iNb,cov=jNb})
end
if fNb%60==0 then
task.wait()
end
end
table.sort(eNb,function(pNb,qNb)
return pNb.sc>qNb.sc
end)
for rNb,sNb in ipairs(eNb)do
local tNb=Q.valid(sNb.pos,NMb.data)
if tNb then
j.log(1,Bxc[3000],string.format(Bxc[3001],N.name(NMb.id),Q.CONTROL_WORDS[bNb],math.floor(cNb*100+0.5)))
return tNb,sNb.cov,cNb
end
if rNb%20==0 then
task.wait()
end
end
return nil
end
function Q.holdSpot(uNb)
local vNb,wNb=W.holds(uNb.id)
if not vNb then
return nil
end
local xNb,yNb={},0
for zNb,ANb in ipairs(Q.mine or{})do
local BNb=ANb._stats
local CNb=BNb.id.Value
if BNb:FindFirstChild(Bxc[1626])and not N.isFarm(CNb)and not N.allyBuff(CNb)and CNb~=uNb.id then
local DNb,ENb=pcall(Q.liveDps,ANb,CNb)
ENb=DNb and tonumber(ENb)or 0
if ENb>0 then
table.insert(xNb,{p=M.flat(ANb:GetPivot().Position),r=BNb.range.Value,d=ENb})
yNb=yNb+ENb
end
end
end
if#xNb==0 or yNb<=0 then
