JNb=JNb+LNb.d
end
end
FNb[GNb]=JNb/yNb
end
local MNb=N.range(uNb.u,math.min(tonumber(wNb)or 0,3,N.rows(uNb.id).max))*((Q.info and tonumber(Q.info.rangeScale))or 1)
