local HOb=(Q.kind==Bxc[1509]or Q.style==Bxc[2702]or Q.style==Bxc[2705])and not ZNb and not(wOb and wOb.leak)and not N.isFarm(YNb.id)and N.range(YNb.u,N.rows(YNb.id).max)*FOb or nil
local IOb=N.allyBuff(YNb.id)
