local fQb=(M.flat(eQb.pos)-cQb).Magnitude
if eQb.prog<uPb then
if fQb<=vPb then
ZPb=ZPb-2
end
elseif fQb<=GOb then
ZPb=ZPb+1
end
end
elseif EPb then
