for hQb,iQb in ipairs(Q.samples)do
if(M.flat(iQb.pos)-gQb).Magnitude<=GOb then
ZPb=ZPb+iQb.prog*iQb.prog
end
end
elseif IOb and APb>0 then
local jQb=0
for kQb,lQb in ipairs(zPb)do
