function Q.lookAt(CQb)
local DQb,EQb=math.huge,nil
for FQb,GQb in ipairs(Q.samples)do
local HQb=(M.flat(GQb.pos)-M.flat(CQb)).Magnitude
if HQb<DQb then
DQb,EQb=HQb,GQb.pos
end
end
local IQb=EQb and M.flat(EQb-CQb)or Vector3 .new(0,0,-1)
return IQb.Magnitude>0.01 and IQb.Unit or Vector3 .new(0,0,-1)
end
function Q.place(JQb,KQb)
local LQb=N.isFarm(JQb.id)
local MQb,NQb=Q.bestSpot(JQb,LQb or(Q.random and N.idol(JQb.id)),(Q.trainee~=nil and JQb.uuid==Q.trainee)or N.ENTRY[JQb.id]==true or(Q.studyEntry==true and JQb.id==Q.trialId))
if not MQb then
Q.noSpot[JQb.uuid]=(Q.noSpot[JQb.uuid]or 0)+1
j.status(Bxc[2995],Bxc[3005]..N.name(JQb.id))
return false
end
local OQb=Q.money()
local PQb,QQb=j.request(Bxc[3006],Bxc[3007],JQb.uuid,H.Util.CFramePLV(MQb,Q.lookAt(MQb)))
if PQb and QQb then
Q.spent=Q.spent+(JQb.data.cost or 0)
table.insert(Q.actions,string.format(Bxc[3008],N.name(JQb.id)))
j.log(1,Bxc[3000],string.format(Bxc[3009],N.name(JQb.id),Q.spotKey(MQb),NQb,KQb))
Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=JQb.id,x=math.floor(MQb.X),z=math.floor(MQb.Z),cover=math.floor((NQb or 0)+0.5),why=tostring(KQb):sub(1,90)})
j.status(Bxc[2995],string.format(Bxc[3010],N.name(JQb.id),KQb))
Q.placedAt=Q.placedAt or{}
Q.placedAt[JQb.uuid]=(Q.placedAt[JQb.uuid]or 0)+1
return true
end
if OQb>=(JQb.data.cost or 0)and Q.random then
Q.placeFail=Q.placeFail or{}
Q.placeFail[JQb.uuid]=(Q.placeFail[JQb.uuid]or 0)+1
if Q.placeFail[JQb.uuid]>=2 then
Q.noSpot[JQb.uuid]=3
j.log(1,Bxc[3000],string.format(Bxc[3011],N.name(JQb.id),Q.fieldCount(),Q.FIELD_MAX))
end
end
if PQb and OQb>=(JQb.data.cost or 0)and not Q.random then
local RQb=Q.spotKey(MQb)
Q.refused[RQb]=true
local SQb=Q.mapKey()
J.blocked[SQb]=J.blocked[SQb]or{}
if not Q.refusedRun[RQb]then
J.blocked[SQb][RQb]=(tonumber(J.blocked[SQb][RQb])or 0)+1
Q.refusedRun[RQb]=true
end
Q.refusals=(Q.refusals or 0)+1
Q.unitRefusals[JQb.uuid]=(Q.unitRefusals[JQb.uuid]or 0)+1
if Q.unitRefusals[JQb.uuid]>=3 then
local TQb=math.max(1,Q.count(JQb.uuid))
if J.caps[JQb.uuid]~=TQb then
J.caps[JQb.uuid]=TQb
j.log(1,Bxc[3000],string.format(Bxc[3012],N.name(JQb.id),TQb))
end
end
j.log(2,Bxc[3000],Bxc[3013]..RQb..Bxc[2036]..N.name(JQb.id))
j.saveSoon()
end
return false
end
function Q.count(UQb)
local VQb=0
for WQb,XQb in ipairs({workspace._UNITS,workspace:FindFirstChild(Bxc[3014])})do
if XQb then
for YQb,ZQb in ipairs(XQb:GetChildren())do
local _Qb=ZQb:FindFirstChild(Bxc[1548])
if _Qb and _Qb:FindFirstChild(Bxc[3003])and _Qb.player.Value==G and _Qb.uuid.Value==UQb then
VQb=VQb+1
end
end
end
