return VQb
end
function Q.measure()
local aRb,bRb=Q.calRun,Q.info
if not(aRb and bRb)then
return
end
pcall(Q.sampleHelpers)
local cRb=M.now()
local dRb=Q.wave()
local eRb=Q.money()
if not aRb.start and eRb>0 and#Q.mine==0 then
aRb.start=eRb
end
if dRb~=aRb.lastW then
if Q.trialId and dRb>0 then
Q.trialTrace=Q.trialTrace or{}
local fRb,gRb,hRb,iRb=0,{},0,0
for jRb,kRb in ipairs(Q.mine)do
local lRb=kRb._stats
if lRb.id.Value==Q.trialId then
fRb=fRb+1
table.insert(gRb,tostring(lRb.upgrade.Value))
elseif not N.isFarm(lRb.id.Value)then
iRb=iRb+1
end
end
pcall(Q.sampleHelpers,true)
for mRb,nRb in pairs(Q.ownDealt)do
if nRb.id==Q.trialId then
hRb=hRb+nRb.v
end
end
local oRb=0
for pRb,qRb in pairs(Q.helperDealt)do
if qRb.owner==Q.trialId then
oRb=oRb+qRb.v
end
end
table.insert(Q.trialTrace,string.format(Bxc[3015],dRb,cRb-(Q.startT or cRb),eRb,table.concat(gRb,Bxc[2104]),iRb,hRb+oRb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[dRb-1]or 0,Q.teamDps or 0))
end
if aRb.lastW and aRb.lastW>0 and aRb.lastWT then
table.insert(aRb.waveSec,cRb-aRb.lastWT)
end
if aRb.paidT and dRb>0 and cRb-aRb.paidT<15 then
table.insert(aRb.skip,cRb-aRb.paidT)
end
aRb.paidT=nil
if dRb>0 then
aRb.alive[tostring(dRb)]=Q.hpAliveRaw or 0
end
aRb.lastW,aRb.lastWT=dRb,cRb
end
