function Q.holdGain(XUb,YUb)
if Q.random or not YUb or not Q.info then
return 0
end
local ZUb=N.attackInfo(YUb.atk,YUb.range)
if(ZUb.stun or 0)<=0 and(ZUb.slowTime or 0)<=0 then
return 0
end
local _Ub=0
for aVb,bVb in ipairs(Q.mine or{})do
local cVb=bVb._stats
local dVb=N.rows(cVb.id.Value)
local eVb=dVb and dVb[math.min(cVb.upgrade.Value,dVb.max)]
local fVb=eVb and eVb.atk and N.attackInfo(eVb.atk,eVb.range)
if fVb and((fVb.stun or 0)>0 or(fVb.slowTime or 0)>0)then
_Ub=_Ub+1
end
end
local gVb,hVb=W.mask(Q.info.map,N.range(XUb.u,0)*(Q.info.rangeScale or 1)),0
for iVb=1,W.BINS do
if gVb[iVb]then
hVb=hVb+1
end
end
local jVb=Q.depth and Q.depth.units>0 and Q.depth.covEnd or 1
local kVb=(N.airFrom(XUb.id)==0)and 1 or(1-(1-H.FLY_GROUND)*math.min(1,Q.info.flyChance or 0))
return V.holdGain(ZUb,Q.teamDps or 0,hVb/(math.max(0.1,jVb)*W.BINS)*kVb,_Ub)
end
function Q.buffGain(lVb)
local mVb=N.allyBuff(lVb.id)
if not mVb then
return 0
end
local nVb=Q.buffShort(mVb)
local oVb=J.stack[mVb.attack]
local pVb=oVb and oVb.stacks and(oVb.cap or 1)or nil
local qVb,rVb=pcall(N.range,lVb.u,0)
rVb=(qVb and tonumber(rVb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local sVb=pVb and I.community and tonumber(mVb.time)and tonumber(mVb.cd)
local function tVb(uVb,vVb)
local wVb=math.floor(uVb*mVb.time/math.max(1,mVb.cd)+0.001)
return math.min(pVb,(1+vVb)^wVb-1)
end
local xVb=0
for yVb,zVb in ipairs(nVb)do
local AVb=0
for BVb,CVb in ipairs(nVb)do
if(CVb.pos-zVb.pos).Magnitude<=rVb then
local DVb=mVb.types[CVb.base]
local EVb=DVb*mVb.uptime
if sVb then
local FVb,GVb=tVb(CVb.n,DVb),CVb.n+1
while GVb<CVb.n+6 and tVb(GVb,DVb)<=FVb+0.001 do
GVb=GVb+1
end
EVb=math.max(0,(tVb(GVb,DVb)-FVb)/(GVb-CVb.n))
elseif pVb then
EVb=math.max(0,math.min(pVb,(CVb.n+1)*DVb*mVb.uptime)-math.min(pVb,CVb.n*DVb*mVb.uptime))
end
AVb=AVb+CVb.dps*EVb
