local W8b=N.range(U8b.u,0)*((Q.info and Q.info.rangeScale)or 1)
local X8b=M.flat(V8b.pos)
local Y8b,Z8b
local _8b=0
for a9b,b9b in ipairs(Q.cands)do
if(M.flat(b9b)-X8b).Magnitude<=W8b then
local c9b=Q.valid(b9b,U8b.data)
_8b=_8b+1
if _8b%40==0 then
task.wait()
end
if c9b then
local d9b,e9b=0,M.flat(c9b)
for f9b,g9b in ipairs(Q.samples)do
if g9b.prog>=V8b.prog and(M.flat(g9b.pos)-e9b).Magnitude<=W8b then
d9b=d9b+1
end
end
if not Z8b or d9b>Z8b then
Y8b,Z8b=c9b,d9b
end
end
end
end
return Y8b,Z8b or 0
end
function Q.focusGain(h9b)
local i9b=Q.focus
if not i9b then
return 1
end
local j9b=h9b._stats
if not j9b:FindFirstChild(Bxc[1626])then
return 1
end
local k9b,l9b=M.flat(h9b:GetPivot().Position),j9b.range.Value
if i9b.fly and not Q.canAir(h9b)then
return 0.02
end
if(k9b-M.flat(i9b.pos)).Magnitude<=l9b then
return 1
end
return(k9b-M.flat(i9b.pos)).Magnitude<=l9b*1.5 and 0.3 or 0.02
end
Q.cashTried=setmetatable({},{__mode=Bxc[1672]})
function Q.lastWaveCash()
if not(Q.total and Q.wave()>=Q.total and not Q.infinite)or Q.spellBusy then
return
end
local m9b=H.session()
local n9b
for o9b,p9b in pairs((m9b and m9b.ingame_spells)or{})do
if p9b==Bxc[3217]then
n9b=o9b
