end
local q9b,r9b
for s9b,t9b in ipairs(Q.mine)do
local u9b=t9b._stats
local v9b=H.Units[u9b.id.Value]
if N.isFarm(u9b.id.Value)and not(v9b and v9b.unsellable)and(Q.cashTried[t9b]or 0)<2 then
local w9b=u9b:FindFirstChild(Bxc[3213])and tonumber(u9b.total_spent.Value)or 0
if not r9b or w9b>r9b then
q9b,r9b=t9b,w9b
end
end
end
if not q9b then
return
end
Q.cashTried[q9b]=(Q.cashTried[q9b]or 0)+1
