Q.spellBusy=true
local y9b=j.request(Bxc[3224],Bxc[3225],n9b,q9b)
Q.spellBusy=false
if y9b then
j.log(1,Bxc[3209],string.format(Bxc[3248],x9b,M.fmt(r9b)))
end
else
local z9b,A9b=j.request(Bxc[2937],Bxc[2938],q9b)
if A9b==true then
j.log(1,Bxc[3000],string.format(Bxc[3249],x9b,M.fmt(r9b)))
elseif Q.cashTried[q9b]>=2 then
j.log(1,Bxc[3000],string.format(Bxc[3250],x9b))
end
