Q.mergeIds={}
function Q.mergeScan()
Q.mergePlan,Q.mergeIds=nil,{}
if not Q.random then
return
end
local B9b=H.session()
local C9b=false
Q.cloneCard=false
for D9b,E9b in pairs((B9b and B9b.ingame_spells)or{})do
if E9b==Bxc[3215]then
C9b=true
elseif E9b==Bxc[3251]then
Q.cloneCard=true
end
end
local F9b={}
local G9b=J.fh.noMerge or{}
for H9b,I9b in ipairs(Q.mine or{})do
local J9b=I9b._stats
local K9b=J9b.id.Value
if not N.isFarm(K9b)and not N.allyBuff(K9b)and not N.idol(K9b)and J9b:FindFirstChild(Bxc[3252])and(G9b[K9b]or 0)<2 then
local L9b,M9b=pcall(Q.liveDps,I9b,K9b)
F9b[K9b]=F9b[K9b]or{}
table.insert(F9b[K9b],{m=I9b,lvl=J9b.upgrade.Value,max=J9b.max_upgrade.Value,dps=L9b and M9b or 0})
end
end
local N9b={}
for O9b,P9b in ipairs(Q.team or{})do
if P9b.hand then
N9b[P9b.id]=true
end
end
local Q9b={}
for R9b,S9b in pairs(F9b)do
table.sort(S9b,function(T9b,U9b)
if T9b.dps~=U9b.dps then
return T9b.dps>U9b.dps
end
return T9b.lvl>U9b.lvl
end)
table.insert(Q9b,{id=R9b,dps=S9b[1].dps*Q.airBoost(S9b[1].m)*Q.reach(S9b[1].m)})
end
table.sort(Q9b,function(V9b,W9b)
return V9b.dps>W9b.dps
end)
for X9b=1,math.min(3,#Q9b)do
Q.mergeIds[Q9b[X9b].id]=true
end
local Y9b
for Z9b,_9b in pairs(F9b)do
local aac=table.clone(_9b)
table.sort(aac,function(bac,cac)
if bac.lvl~=cac.lvl then
return bac.lvl<cac.lvl
end
return bac.dps<cac.dps
end)
for dac,eac in ipairs(aac)do
if eac.m==Q.freshM and dac>1 then
table.remove(aac,dac)
table.insert(aac,1,eac)
break
end
end
local fac,gac,hac,iac
for jac,kac in ipairs(aac)do
local lac,mac=M.flat(kac.m:GetPivot().Position),kac.m._stats.range.Value
local nac,oac,pac=0,0,nil
for qac,rac in ipairs(_9b)do
if rac~=kac and(M.flat(rac.m:GetPivot().Position)-lac).Magnitude<=mac then
nac,oac=nac+rac.dps,oac+1
if not pac or rac.dps>pac.dps then
pac=rac
end
end
end
if oac>0 then
fac,gac,hac,iac=kac,nac,oac,pac
break
end
end
iac=iac or _9b[1]
local sac=iac.dps*Q.airBoost(iac.m)*Q.reach(iac.m)*(Z9b==Q.planId and 2 or 1)
if(Q.mergeIds[Z9b]or Z9b==Q.planId)and(fac or N9b[Z9b])and(not Y9b or sac>Y9b.score)then
Y9b={id=Z9b,top=iac,fresh=fac,near=gac or 0,n=hac or 0,coming=N9b[Z9b],score=sac}
end
end
Q.planId,Q.freshM=Y9b and Y9b.id,Y9b and Y9b.fresh and Y9b.fresh.m
Q.mergeHeldAt=(C9b and Y9b and Y9b.fresh)and(Q.mergeHeldAt or Q.wave())or nil
if not Y9b then
return j.status(Bxc[3192],Bxc[3253])
end
local tac,uac=Q.wave(),(Q.total or 30)-Q.wave()
local vac=(Q.pressure or 0)>=math.min(I.dangerReach,((Q.depth and Q.depth.units>0 and Q.depth.covEnd)or 1)*0.9)
local wac=Y9b.fresh
local xac=not vac and uac>3
Y9b.waits=wac and wac.lvl<=Y9b.top.lvl and Y9b.top.lvl<Y9b.top.max and xac or false
local yac=(not wac or wac.lvl>=Y9b.top.lvl)and Y9b.coming and xac
local zac=Q.cloneCard and Y9b.top.lvl>=Y9b.top.max and xac
local Aac=wac and wac.lvl>Y9b.top.lvl and Y9b.near<0.3*wac.dps
Y9b.ready=C9b and wac~=nil and not Aac and(not(Y9b.waits or yac or zac)or tac-(Q.mergeHeldAt or tac)>=5)
Q.holdNoCardAt=(Y9b.waits and not C9b)and(Q.holdNoCardAt or tac)or nil
Y9b.hold=Y9b.waits and(C9b or tac-(Q.holdNoCardAt or tac)<4)
Q.mergePlan=Y9b
j.status(Bxc[3192],wac and string.format(Bxc[3254],N.name(Y9b.id),Y9b.n,Y9b.n==1 and Bxc[3255]or Bxc[3256],wac.lvl,Y9b.ready and Bxc[3257]or(C9b and Bxc[3258]or Bxc[3259]))or string.format(Bxc[3260],N.name(Y9b.id)))
end
function Q.mergeHold(Bac)
