return Cac and Cac.hold and Cac.fresh and Cac.fresh.m==Bac or false
end
function Q.mergeBoost(Dac)
local Eac=Q.mergePlan
if not(Eac and Eac.top.m==Dac and(Eac.fresh or Eac.coming))then
return 1
end
return Q.mergeHeldAt and 2 or 1.3
