function Q.mergeMeasure(Mac)
local Nac=Q.mergeBefore
if not Nac then
return
end
task.delay(2,function()
if not(Mac and Mac.Parent)then
return
end
local Oac,Pac=pcall(Q.liveDps,Mac,Mac._stats.id.Value)
if not Oac then
return
end
local Qac=Nac.own+1.5*Nac.near
local Rac=J.fh.merge or{n=0,ratio=0}
if Qac>0 then
Rac.n,Rac.ratio=Rac.n+1,Rac.ratio+Pac/Qac
end
J.fh.merge=Rac
local Sac=Mac._stats.id.Value
J.fh.noMerge=J.fh.noMerge or{}
