if Uac>0 and Tac<0.1*Uac then
J.fh.noMerge[Sac]=(J.fh.noMerge[Sac]or 0)+1
elseif Uac>0 and Tac>=0.5*Uac then
J.fh.noMerge[Sac]=nil
end
j.log(1,Bxc[3209],string.format(Bxc[3261],N.name(Mac._stats.id.Value),M.fmt(Nac.own),M.fmt(Pac),Nac.lvl,M.fmt(Nac.near),M.fmt(Qac),Nac.top))
end)
end
function Q.farmMergeOk()
local Vac=J.fh.farmMerge
if not(Vac and Vac.n>0)then
