end
return Vac.ratio/Vac.n>=0.8
end
function Q.farmMergePair()
local Wac={}
for Xac,Yac in ipairs(Q.mine or{})do
local Zac=Yac._stats.id.Value
if N.isFarm(Zac)and Yac._stats:FindFirstChild(Bxc[1581])then
Wac[Zac]=Wac[Zac]or{}
table.insert(Wac[Zac],Yac)
end
end
for _ac,abc in pairs(Wac)do
if#abc>=2 then
table.sort(abc,function(bbc,cbc)
return bbc._stats.upgrade.Value<cbc._stats.upgrade.Value
end)
for dbc,ebc in ipairs(abc)do
local fbc,gbc=M.flat(ebc:GetPivot().Position),ebc._stats.range.Value
local hbc,ibc=0,0
for jbc,kbc in ipairs(abc)do
if kbc~=ebc and(M.flat(kbc:GetPivot().Position)-fbc).Magnitude<=gbc then
hbc,ibc=hbc+(tonumber(kbc._stats.farm_amount.Value)or 0),ibc+1
end
end
if ibc>0 then
return ebc,hbc,ibc
end
end
end
end
end
function Q.farmMergeSpot(lbc)
