local ubc,vbc=Q.IDOL_PRIOR.dmg,Q.IDOL_PRIOR.cost
if tbc and tbc.n>0 then
ubc,vbc=tbc.dmg/tbc.n,tbc.cost/tbc.n
end
return math.max(0,ubc)+math.max(0,vbc)*0.5
