function Q.idolMeasure()
local wbc
for xbc,ybc in ipairs(Q.mine)do
local zbc=ybc._stats.id.Value
local Abc=ybc._stats:FindFirstChild(Bxc[1623])
if not N.isFarm(zbc)and not N.idol(zbc)and Abc and Abc.Value>0 then
wbc=ybc
break
end
end
if not wbc then
return
end
local Bbc=wbc._stats
local function Cbc()
local Dbc,Ebc=pcall(H.USC.calculate_upgrade_cost_multiplier,wbc,H.session())
local Fbc=Bbc:FindFirstChild(Bxc[3074])and tonumber(Bbc.buff_damage_multiplier.Value)or 0
return Bbc.damage.Value*(1+Fbc),Dbc and tonumber(Ebc)or nil
end
local Gbc,Hbc=Cbc()
local Ibc=Bbc.upgrade.Value
task.delay(3,function()
if not wbc.Parent or Bbc.upgrade.Value~=Ibc then
return
end
local Jbc,Kbc=Cbc()
if not(Hbc and Kbc and Hbc>0 and Gbc>0)then
return
end
if Jbc==Gbc and Kbc==Hbc then
return j.log(2,Bxc[3067],Bxc[3263])
end
local Lbc=J.fh.idol or{n=0,dmg=0,cost=0}
Lbc.n,Lbc.dmg,Lbc.cost=Lbc.n+1,Lbc.dmg+(Jbc/Gbc-1),Lbc.cost+(1-Kbc/Hbc)
J.fh.idol=Lbc
j.log(1,Bxc[3067],string.format(Bxc[3264],N.name(Bbc.id.Value),(Jbc/Gbc-1)*100,(1-Kbc/Hbc)*100))
end)
end
function Q.spells()
local Mbc=H.session()
local Nbc=Mbc and Mbc.ingame_spells
if type(Nbc)~=Bxc[1489]or Q.spellBusy then
return
end
local Obc=Q.money()
local Pbc=(Q.pressure or 0)>=math.min(I.dangerReach,((Q.depth and Q.depth.units>0 and Q.depth.covEnd)or 1)*0.9)
local Qbc,Rbc,Sbc
for Tbc,Ubc in ipairs(Q.mine)do
local Vbc=Ubc._stats.id.Value
if not N.isFarm(Vbc)and not N.allyBuff(Vbc)and Vbc~=Bxc[2942]then
local Wbc,Xbc=pcall(Q.liveDps,Ubc,Vbc)
local Ybc=Wbc and Xbc and Xbc*Q.airBoost(Ubc)*Q.reach(Ubc)
if Ybc and(not Sbc or Ybc>Sbc)then
Qbc,Rbc,Sbc=Ubc,Xbc,Ybc
end
end
