local Zbc=Q.mergePlan
local _bc={}
for acc,bcc in pairs(Nbc)do
table.insert(_bc,{slot=acc,spell=bcc,rank=Q.SPELL_ORDER[bcc]or 9})
end
table.sort(_bc,function(ccc,dcc)
return ccc.rank<dcc.rank
end)
Q.spellWant=nil
Q.cloneNote=nil
for ecc,fcc in ipairs(_bc)do
local gcc,hcc=fcc.slot,fcc.spell
local icc,jcc
local kcc
for lcc,mcc in ipairs(Q.mine)do
if mcc._stats.id.Value==Bxc[2942]then
kcc=mcc
end
end
local ncc=kcc and(Q.buffCount[kcc]or 0)<2
if hcc==Bxc[3265]and Obc>=1000 and(ncc or Qbc)then
if ncc then
icc,jcc=kcc,Bxc[3266]
else
icc,jcc=Qbc,Bxc[3267]
end
elseif hcc==Bxc[3215]and Zbc and Zbc.ready then
if Obc>=1000 then
icc,jcc=Zbc.fresh.m,string.format(Bxc[3268],Zbc.n,Zbc.n==1 and Bxc[3255]or Bxc[3256])
Q.mergeBefore={own=Zbc.fresh.dps,near=Zbc.near,lvl=Zbc.fresh.lvl,top=Zbc.top.lvl}
else
Q.spellWant=Q.spellWant or{cost=1000,why=Bxc[3269]..N.name(Zbc.id)}
end
elseif hcc==Bxc[3215]and Obc>=1000 and not Pbc and not(Zbc and Zbc.fresh)and Q.farmMergeOk()and Q.farmMergePair()then
local occ,pcc,qcc=Q.farmMergePair()
icc=occ
jcc=string.format(Bxc[3270],qcc,N.name(occ._stats.id.Value))
Q.farmMergeBefore={own=tonumber(occ._stats.farm_amount.Value)or 0,inc=pcc}
elseif hcc==Bxc[3251]then
local rcc=not Pbc and Zbc and Zbc.fresh and Zbc.top.lvl<Zbc.top.max
Q.cloneWaitAt=rcc and(Q.cloneWaitAt or Q.wave())or nil
local scc=rcc and Q.wave()-Q.cloneWaitAt<5
local tcc,ucc
if not Pbc and Zbc and Zbc.fresh and Zbc.top.lvl>=Zbc.top.max then
tcc,ucc=Zbc.top.m,Bxc[3271]
elseif not scc and Qbc then
tcc,ucc=Qbc,Pbc and Bxc[3272]or Bxc[3273]
end
if scc then
Q.cloneNote=string.format(Bxc[3274],N.name(Zbc.id),Zbc.top.lvl,Zbc.top.max,5-(Q.wave()-Q.cloneWaitAt))
end
if tcc and Obc>=5000 then
icc,jcc=tcc,ucc
elseif tcc then
local vcc,wcc=pcall(Q.liveDps,tcc,tcc._stats.id.Value)
wcc=vcc and tonumber(wcc)or 0
if wcc>=(Q.bestRate or 0)*5000*0.5 then
Q.spellWant=Q.spellWant or{cost=5000,why=Bxc[3275]..N.name(tcc._stats.id.Value),rate=wcc/5000}
Q.cloneNote=Bxc[3276]..N.name(tcc._stats.id.Value)
else
Q.cloneNote=string.format(Bxc[3277],N.name(tcc._stats.id.Value),M.fmt(wcc),M.fmt((Q.bestRate or 0)*5000))
end
end
elseif hcc==Bxc[3211]and not Pbc and Q.wave()>=8 and not Q.hasGeneral()then
local xcc,ycc=Q.ritualTarget()
if xcc and Obc>=10000 then
icc,jcc=xcc,ycc
elseif xcc then
Q.spellWant=Q.spellWant or{cost=10000,why=Bxc[3278]..ycc..Bxc[1806]}
end
elseif hcc==Bxc[1871]and Obc>=10000 and not Pbc and Q.summonWorth()then
icc,jcc=false,Bxc[3279]
elseif hcc==Bxc[3216]and Obc>=2500 and not Pbc and Q.summonWorth()then
icc,jcc=false,Bxc[3280]
end
if jcc then
Q.spellBusy=true
local zcc={}
for Acc,Bcc in ipairs(workspace._UNITS:GetChildren())do
zcc[Bcc]=true
end
local Ccc
if icc then
local Dcc=icc._stats
local Ecc,Fcc=pcall(Q.liveDps,icc,Dcc.id.Value)
Ccc={id=Dcc.id.Value,pos=icc:GetPivot().Position,dps=Ecc and tonumber(Fcc)or 0,lvl=Dcc.upgrade.Value,spent=Dcc:FindFirstChild(Bxc[3213])and tonumber(Dcc.total_spent.Value)or 0}
end
task.spawn(function()
local Gcc
if icc then
Gcc=j.request(Bxc[3224],Bxc[3225],gcc,icc)
else
Gcc=j.request(Bxc[3224],Bxc[3225],gcc)
end
task.wait(1.5)
local Hcc=icc and N.name(icc._stats.id.Value)or Bxc[418]
if Gcc and(H.session().ingame_spells or{})[gcc]~=hcc then
j.log(1,Bxc[3209],string.format(Bxc[3281],Q.SPELL_NAMES[hcc]or tostring(hcc),icc and(Bxc[1760]..Hcc)or Bxc[418],jcc))
j.status(Bxc[3101],string.format(Bxc[3282],Q.SPELL_NAMES[hcc]or tostring(hcc),icc and(Bxc[1760]..Hcc)or Bxc[418],jcc))
if hcc==Bxc[3215]then
if Ccc and N.isFarm(Ccc.id)then
pcall(Q.farmMergeMeasure,icc)
else
pcall(Q.mergeMeasure,icc)
end
end
if hcc==Bxc[3265]and icc then
Q.buffCount[icc]=(Q.buffCount[icc]or 0)+1
end
if(hcc==Bxc[3251]or hcc==Bxc[3211])and Ccc then
pcall(Q.newUnitMeasure,hcc,icc,Hcc,Ccc,zcc)
end
else
j.backoff(Bxc[3224],15)
j.log(2,Bxc[3209],tostring(hcc)..Bxc[3283]..(icc and(Bxc[1760]..Hcc)or Bxc[418]))
end
Q.spellBusy=false
end)
return
end
end
end
function Q.trainCount()
local Icc=J.train.on
if not(Icc and Q.trainee)then
return
end
local Jcc=0
for Kcc,Lcc in ipairs(Q.mine)do
local Mcc=Lcc._stats
local Ncc=Mcc:FindFirstChild(Bxc[3003])and Mcc.uuid.Value
local Occ=Ncc==Q.trainee and Mcc:FindFirstChild(Icc.what==Bxc[1988]and Bxc[3284]or Bxc[1956])
if Occ then
Jcc=Jcc+(tonumber(Occ.Value)or 0)
end
end
Q.trainTk=math.max(Q.trainTk or 0,Jcc)
j.status(Bxc[2352],string.format(Bxc[3285],N.name(Icc.id),Q.trainTk,Icc.what,M.fmt(Icc.have+(Icc.got or 0)+Q.trainTk),M.fmt(Icc.need)))
end
function Q.trainDone(Pcc,Qcc)
local Rcc=J.train.on
if not(Rcc and Q.trainee)then
return
end
Q.trainCount()
local Scc=Q.trainTk or 0
Rcc.got=(Rcc.got or 0)+Scc
local Tcc=J.trainSim[Pcc]and tonumber(J.trainSim[Pcc].tk)
if not Q.joinedMid then
local Ucc=J.train.real[Pcc]or{n=0,sum=0}
Ucc.n,Ucc.sum=Ucc.n+1,Ucc.sum+Scc
J.train.real[Pcc]=Ucc
if Tcc and Tcc>0 then
local Vcc=J.train.cal
Vcc.real,Vcc.sim,Vcc.n=(Vcc.real or 0)+Scc,(Vcc.sim or 0)+Tcc,(Vcc.n or 0)+1
end
end
table.insert(J.train.log,1,{key=Pcc,got=Scc,won=Qcc,at=os.time()})
while#J.train.log>20 do
